package vn.edu.eaut.lab6.listener; import jakarta.servlet.annotation.WebListener;import jakarta.servlet.http.*;@WebListener public class SessionLogListener implements HttpSessionListener{public void sessionCreated(HttpSessionEvent e){System.out.println("Session moi duoc tao: "+e.getSession().getId());}public void sessionDestroyed(HttpSessionEvent e){System.out.println("Session da bi huy: "+e.getSession().getId());}}
